d_k=\begin{cases}
    \frac{-1}{2j}, & k=-2,\\
    \frac{1}{2j}, & k=2,\\
    0, & k\neq \pm 2.
\end{cases}

d_k=\begin{cases}
    \frac{1}{2} e^{-j(-1) 2\pi \left(\frac{1}{4}\right)}=\frac{1}{2} e^{j\pi/2}=\frac{j}{2}, & k=-1,\\
    \frac{1}{2} e^{-j(1) 2\pi \left(\frac{1}{4}\right)}=\frac{1}{2} e^{-j\pi/2}=\frac{-j}{2}, & k=1,\\
    0, & k\neq \pm 1.
\end{cases}

